const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define La Jolla, California coastal region
  const laJollaPoint = ee.Geometry.Point([-117.27, 32.85]);
  const region = laJollaPoint.buffer(10000); // 10km buffer around the point

  // NOAA OISST collection
  const sst = ee.ImageCollection('NOAA/OISST/AVHRR/V02');

  // Filter for August 1, 2018 and August 1, 2017
  const sst2018 = sst.filterDate('2018-08-01', '2018-08-02')
    .select('sst');
  const sst2017 = sst.filterDate('2017-08-01', '2017-08-02')
    .select('sst');

  // Check data availability
  const size2018 = sst2018.size().getInfo();
  const size2017 = sst2017.size().getInfo();

  print(`2018 Images: ${size2018}`);
  print(`2017 Images: ${size2017}`);

  if (size2018 === 0 || size2017 === 0) {
    print('No data available for one or both dates.');
    print('C1');
    return;
  }

  // Get mean SST for both dates
  const img2018 = sst2018.first();
  const img2017 = sst2017.first();

  // Count valid pixels
  const count2018 = img2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  const count2017 = img2017.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  print(`Valid pixels 2018: ${count2018}, 2017: ${count2017}`);

  if (count2018 === 0 || count2017 === 0) {
    print('No valid pixels after processing.');
    print('C2');
    return;
  }

  // Calculate mean SST for each year (convert from Kelvin to Celsius)
  const meanSST2018 = img2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  const meanSST2017 = img2017.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 25000,
    maxPixels: 1e9
  }).get('sst').getInfo();

  // Convert from Kelvin to Celsius
  const sst2018C = meanSST2018 - 273.15;
  const sst2017C = meanSST2017 - 273.15;

  print(`2018 SST: ${sst2018C.toFixed(2)}°C`);
  print(`2017 SST: ${sst2017C.toFixed(2)}°C`);

  // Validate results
  if (sst2018C === null || sst2017C === null || 
      isNaN(sst2018C) || isNaN(sst2017C) ||
      sst2018C < -5 || sst2018C > 40 || 
      sst2017C < -5 || sst2017C > 40) {
    print('Invalid SST values.');
    print('C3');
    return;
  }

  // Compare temperatures
  if (sst2018C > sst2017C) {
    print(`2018 was warmer (${(sst2018C - sst2017C).toFixed(2)}°C difference)`);
    print('A');
  } else {
    print(`2018 was not warmer (${(sst2017C - sst2018C).toFixed(2)}°C cooler)`);
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
